// Checks that the pkg-config file generated by native/darwin points to the absolute path of the current location when the workspace is moved and rebuilt,
// and that the file is not rewritten when the content is the same.
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { copyFileSync, mkdirSync, mkdtempSync, readFileSync, realpathSync, renameSync, rmSync, statSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import test from "node:test";
import { macosMinimum } from "../macos-minimum.mjs";

const makefile = fileURLToPath(new URL("../../native/darwin/Makefile", import.meta.url));
const workspace = fileURLToPath(new URL("../../", import.meta.url));
// The declared macOS minimum as a regular expression.
const minimum = macosMinimum(workspace).replaceAll(".", "\\.");

function pkgconfigFixture(t) {
  const dir = realpathSync(mkdtempSync(join(tmpdir(), "soksak-pkgconfig-")));
  t.after(() => rmSync(dir, { recursive: true }));
  const before = join(dir, "before/native/darwin");
  mkdirSync(join(before, "src"), { recursive: true });
  copyFileSync(makefile, join(before, "Makefile"));
  // The native Makefile reads the macOS minimum from the Makefile of the repository.
  copyFileSync(join(workspace, "Makefile"), join(dir, "before/Makefile"));
  const generate = (directory, packages = ["soksak-darwin"]) => execFileSync("make", ["-C", directory,
    ...packages.map((name) => join(directory, `build/${name}.pc`))], { encoding: "utf8" });
  return { dir, before, generate };
}

test("generated pkg-config file follows a relocated workspace", { timeout: 10000 }, (t) => {
  const { dir, before, generate } = pkgconfigFixture(t);
  generate(before);

  renameSync(join(dir, "before"), join(dir, "after"));
  const after = join(dir, "after/native/darwin");
  const pc = join(after, "build/soksak-darwin.pc");
  generate(after);
  const written = statSync(pc).mtimeMs;
  const flags = execFileSync("pkg-config", ["--cflags", "--libs", "soksak-darwin"], {
    encoding: "utf8",
    env: { ...process.env, PKG_CONFIG_PATH: join(after, "build") },
  });
  const paths = (option) => flags.trim().split(/\s+/).filter((flag) => flag.startsWith(option)).map((flag) => flag.slice(2));
  assert.deepEqual(paths("-I"), [join(after, "src")], flags);
  assert.deepEqual(paths("-L"), [join(after, "build")], flags);
  assert.doesNotMatch(readFileSync(pc, "utf8"), /pcfiledir/);

  generate(after);
  assert.equal(statSync(pc).mtimeMs, written, "an unchanged pkg-config file was rewritten");
});

test("Tauri app and bundled CLI Cargo commands use the declared deployment target", { timeout: 10000 }, () => {
  for (const target of ["build-tauriv2", "build-tauriv2-release"]) {
    const output = execFileSync("make", ["-n", "-o", "build-native", "-o", "build", "-o", "build-registry", "-o", "copy-frontend-tauriv2", target], {
      cwd: workspace,
      encoding: "utf8",
      env: { ...process.env, MACOSX_DEPLOYMENT_TARGET: "13.0" },
    });
    const cargo = output.split(/\r?\n/).filter((line) => /\bcargo build\b.*-p (?:sok-tauriv2|soksak-sok)(?:\s|$)/.test(line));
    assert.equal(cargo.length, 2, `${target} must expand to one app build and one bundled CLI build:\n${output}`);
    assert.match(cargo[0], /^MACOSX_DEPLOYMENT_TARGET=14\.4 (?:\S*\/)?cargo build\b.*-p sok-tauriv2(?:\s|$)/, `${target} app build: ${cargo[0]}`);
    assert.match(cargo[1], /^MACOSX_DEPLOYMENT_TARGET=14\.4 (?:\S*\/)?cargo build\b.*-p soksak-sok(?:\s|$)/, `${target} bundled CLI build: ${cargo[1]}`);
    for (const command of cargo) assert.match(command, /--locked/, `${target} does not preserve the Cargo.lock: ${command}`);
  }
});

test("registry and workspace lint targets use the tracked Cargo lockfile", { timeout: 10000 }, () => {
  const registry = execFileSync("make", ["-n", "-o", "build-native", "build-registry"], {
    cwd: workspace, encoding: "utf8",
  });
  assert.match(registry, /cargo build --locked -p soksak-sok/, registry);
  const clippy = execFileSync("make", ["-n", "-o", "build-native", "-o", "build", "-o", "build-registry", "-o", "copy-frontend-tauriv2", "check-rust-clippy"], {
    cwd: workspace, encoding: "utf8",
  });
  const calls = clippy.split(/\r?\n/).filter((line) => /\bcargo clippy\b/.test(line));
  assert.equal(calls.length, 2, clippy);
  for (const call of calls) assert.match(call, /cargo clippy --locked/, call);
});

test("per-host checks build only the selected host and core frontend", { timeout: 10000 }, () => {
  for (const [host, target] of [["wailsv3", "test-wailsv3"], ["tauriv2", "test-tauriv2"]]) {
    const output = execFileSync("make", ["-n", "-o", "build-native", "-o", "build", target], {
      cwd: workspace, encoding: "utf8",
    });
    assert.match(output, new RegExp(`sok-copy-frontend src/frontend --diagnostics`), output);
    assert.match(output, new RegExp(`test-hosts\\.mjs --host ${host}`), output);
    assert.doesNotMatch(output, /workspace-registry\.mjs/, output);
    assert.doesNotMatch(output, new RegExp(`--host ${host === "wailsv3" ? "tauriv2" : "wailsv3"}`), output);
  }
});

test("the mygo application stages its view root, not a main page", { timeout: 10000 }, () => {
  for (const [target, flags] of [["copy-core-frontend-mygo", /sok-copy-frontend src\/frontend --no-main-page --diagnostics/], ["build-mygo", /sok-copy-frontend src\/frontend --no-main-page --diagnostics --registry-index/], ["build-mygo-release", /sok-copy-frontend src\/frontend --no-main-page/]]) {
    const output = execFileSync("make", ["-n", "-o", "build-native", "-o", "build", "-o", "build-registry", target], { cwd: workspace, encoding: "utf8" });
    assert.match(output, flags, output);
  }
  const builds = (output) => {
    const commands = output.split(/\r?\n/).filter((line) => /\bgo build -C (?:apps\/mygo|packages\/sok\/go)\s/.test(line));
    assert.equal(commands.length, 2, `one application and one bundled CLI build are required:\n${output}`);
    for (const command of commands) {
      assert.match(command, new RegExp(`^CGO_ENABLED=0 MACOSX_DEPLOYMENT_TARGET=${minimum} go build `), command);
      assert.doesNotMatch(command, /-extldflags|CGO_CFLAGS|CGO_LDFLAGS/, command);
    }
    return commands;
  };
  const build = execFileSync("make", ["-n", "-o", "build-native", "-o", "build", "-o", "build-registry", "build-mygo"], { cwd: workspace, encoding: "utf8" });
  const debug = builds(build);
  assert.match(debug[0], /go build -C apps\/mygo -tags "diagnostics dev" -o \S+\/Contents\/MacOS\/sok-mygo \.\/src$/, debug[0]);
  assert.match(debug[1], /go build -C packages\/sok\/go\s+-tags "diagnostics dev mygo" -o \S+\/Contents\/MacOS\/sok \.\/src\/cmd\/sok$/, debug[1]);
  for (const diagnostics of ["", "1"]) {
    const release = execFileSync("make", ["-n", "-o", "build-native", "-o", "build", "-o", "build-registry", `DIAGNOSTIC_RELEASE=${diagnostics}`, "build-mygo-release"], { cwd: workspace, encoding: "utf8" });
    const commands = builds(release);
    const appTags = diagnostics ? String.raw`-tags diagnostics\s+` : '';
    const cliTags = diagnostics ? 'diagnostics mygo' : 'mygo';
    assert.match(commands[0], new RegExp(String.raw`go build -C apps/mygo -trimpath\s+${appTags}-ldflags "-s -w" -o \S+/Contents/MacOS/sok-mygo \./src$`), commands[0]);
    assert.match(commands[1], new RegExp(String.raw`go build -C packages/sok/go -trimpath -ldflags "-s -w" -tags "${cliTags}" -o \S+/Contents/MacOS/sok \./src/cmd/sok$`), commands[1]);
    if (!diagnostics) assert.doesNotMatch(commands[0], /-tags/, commands[0]);
  }
});

test("Rust clippy stages only the core frontend and avoids the workspace registry", { timeout: 10000 }, () => {
  const output = execFileSync("make", ["-n", "-o", "build-native", "-o", "build", "check-rust-clippy"], {
    cwd: workspace, encoding: "utf8",
  });
  assert.match(output, /sok-copy-frontend src\/frontend --diagnostics/, output);
  assert.match(output, /cargo clippy --locked/, output);
  assert.doesNotMatch(output, /workspace-registry\.mjs/, output);
});

test("native and paired host contract checks use core-only frontend stages", { timeout: 10000 }, () => {
  for (const target of ["test-native", "test-hosts"]) {
    const output = execFileSync("make", ["-n", "-o", "build-native", "-o", "build", target], {
      cwd: workspace, encoding: "utf8",
    });
    assert.match(output, /sok-copy-frontend src\/frontend --diagnostics/, output);
    assert.match(output, /test-hosts\.mjs/, output);
    assert.doesNotMatch(output, /workspace-registry\.mjs/, output);
  }
});

test("release host checks audit only their own optimized bundle", { timeout: 10000 }, () => {
  for (const [host, target, bundle] of [
    ["wailsv3", "check-release-wailsv3", "--wailsv3-bundle \"target/release/wailsv3/soksak.app\""],
    ["tauriv2", "check-release-tauriv2", "--tauriv2-bundle \"target/release/tauriv2/soksak.app\""],
    ["mygo", "check-release-mygo", "--mygo-bundle \"target/release/mygo/soksak.app\""],
  ]) {
    const output = execFileSync("make", ["-n", "-o", "build-native", "-o", "build", target], {
      cwd: workspace, encoding: "utf8",
    });
    assert.ok(output.includes(`check-release.mjs --host ${host} --macos-minimum ${macosMinimum(workspace)} ${bundle}`), output);
    for (const other of ["wailsv3", "tauriv2", "mygo"].filter((name) => name !== host)) {
      assert.doesNotMatch(output, new RegExp(`--${other}-bundle`), output);
    }
    assert.doesNotMatch(output, /workspace-registry\.mjs/, output);
  }
});

test("native artifact variables follow relocation and preserve unchanged pkg-config files", { timeout: 10000 }, (t) => {
  const fixture = pkgconfigFixture(t);
  const { dir, before } = fixture;
  const generate = (directory) => fixture.generate(directory, ["soksak-darwin", "soksak-host-test"]);
  const artifacts = (directory) => {
    const result = {};
    for (const [pkg, variables] of [
      ["soksak-darwin", ["static_library", "dynamic_library"]],
      ["soksak-host-test", ["static_library", "dynamic_library", "callback_abi_library", "callback_worker_library"]],
    ]) {
      result[pkg] = {};
      for (const variable of variables) result[pkg][variable] = execFileSync("pkg-config", [`--variable=${variable}`, pkg], {
        encoding: "utf8", env: { ...process.env, PKG_CONFIG_PATH: join(directory, "build") },
      }).trim();
    }
    return result;
  };
  const expected = (directory) => ({
    "soksak-darwin": {
      static_library: join(directory, "build/libsoksak-darwin.a"),
      dynamic_library: join(directory, "build/mygo/libsoksak-darwin.dylib"),
    },
    "soksak-host-test": {
      static_library: join(directory, "build/host-tests/libhost_test.a"),
      dynamic_library: join(directory, "build/host-tests/dynamic/libhost_test.dylib"),
      callback_abi_library: join(directory, "build/libhost_callback_abi.dylib"),
      callback_worker_library: join(directory, "build/libhost_callback_worker.dylib"),
    },
  });
  generate(before);
  assert.deepEqual(artifacts(before), expected(before));
  renameSync(join(dir, "before"), join(dir, "after"));
  const after = join(dir, "after/native/darwin");
  generate(after);
  assert.deepEqual(artifacts(after), expected(after));
  const files = ["soksak-darwin", "soksak-host-test"].map((name) => join(after, `build/${name}.pc`));
  const modified = files.map((file) => statSync(file).mtimeMs);
  for (const file of files) assert.ok(!readFileSync(file, "utf8").includes(before), `${file} retained the old workspace path`);
  generate(after);
  assert.deepEqual(files.map((file) => statSync(file).mtimeMs), modified, "unchanged artifact declarations were rewritten");
});
